"""Check each schema change against v1 by actually writing with one version and reading with the other.

BACKWARD: the new schema can read data written with the old one (upgrade consumers first).
FORWARD:  the old schema can read data written with the new one (upgrade producers first).
FULL:     both.
Usage:  python compat.py
"""
from avro_tools import SCHEMAS, can_read

SAMPLE = {"payment_id": 1, "order_id": 7001, "amount": 450.0, "currency": "THB", "channel": "app",
          "terminal_id": "T-9", "currency_code": "THB"}


def sample_for(version):
    """A record that fits the schema: values from SAMPLE, or a field's default if SAMPLE has none."""
    record = {f["name"]: SAMPLE.get(f["name"], f.get("default")) for f in SCHEMAS[version]["fields"]}
    if version == "v5":
        record["amount"] = "450.00"
    return record


def main():
    for new in sorted(SCHEMAS):
        if new == "v1":
            continue
        backward, why_b = can_read("v1", new, sample_for("v1"))
        forward, why_f = can_read(new, "v1", sample_for(new))
        verdict = "FULL" if backward and forward else "BACKWARD" if backward else "FORWARD" if forward else "NONE"
        print(f"v1 -> {new}: backward {'yes' if backward else 'no'}, forward {'yes' if forward else 'no'} => {verdict}")
        for why in (why_b, why_f):
            if why:
                print(f"    {why}")


if __name__ == "__main__":
    main()
